def check_girth(n, edges):
    import collections
    adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for start_node in range(n):
        # BFS to find shortest cycle
        dist = {start_node: 0}
        parent = {start_node: None}
        queue = collections.deque([start_node])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Cycle found
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 6:
                        return False, cycle_len
    return True, None

